export default {components:{SfPageLayout,SfUserToolbar,SfSegmentedControl,SfBadge,SfFeedback,SfBottomNavigation,SfAiBall},props:{contents:{type:Array,default:()=>[]},user:Object,busy:Boolean},data(){return{selectedId:'',category:'winter',categories:[{value:'summer',label:'Summer'},{value:'winter',label:'Winter'},{value:'sport',label:'Sport'}]}},computed:{visible(){return this.contents.filter(row=>(row.challengeCategory||'winter')===this.category)},selected(){return this.visible.find(row=>row.id===this.selectedId)||this.visible[0]},closed(){return this.selected&&Date.parse(this.selected.challengeRules.endsAt)<=Date.now()},upcoming(){return this.selected&&Date.parse(this.selected.challengeRules.startsAt)>Date.now()},toolbar(){return[{id:'existing-notifications',label:'Notifications',icon:this.asset('img10'),transform:'rotate(180deg) scaleY(-1)'},{id:'plan',label:'Training calendar',icon:this.asset('imgGroup259')},{id:'existing-devices',label:'Devices',icon:this.asset('img11')}]},navigation(){return[{value:'home',label:'Home',action:'home',icon:this.asset('imgFrame')},{value:'workout',label:'Workout',action:'workout',icon:this.asset('imgFrame1')},{value:'challenge',label:'Challenge',action:'existing-challenge',icon:this.asset('imgGroup')},{value:'social',label:'Social',action:'existing-social',icon:this.asset('imgFrame2')}]}},methods:{asset(name){return '/assets/figma/commerce-mvp/challenge/'+name+(['img1','img2','img4','img5','img6','img7','img8','imgEllipse305'].includes(name)?'.png':'.svg')},date(value){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric'}).format(new Date(value))}}}
